From ff9da55625608573cdc8bcb5bd41d75dca7d021e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 00:04:11 +0100
Subject: [PATCH] openconnect: let the SAML login page grow with the dialog

The single sign-on web view had a fixed 640x480 size and the dialog was
capped at 640 px wide, so bigger identity provider pages stayed clipped.
Make 640x480 the minimum, give it the spare height and drop the cap.

BUG: 528259
---
 kded/passworddialog.cpp             | 1 +
 vpn/openconnect/openconnectauth.cpp | 3 ++-
 2 files changed, 3 insertions(+), 1 deletion(-)

diff --git a/kded/passworddialog.cpp b/kded/passworddialog.cpp
index ae796b7ee..deee1a76b 100644
--- a/kded/passworddialog.cpp
+++ b/kded/passworddialog.cpp
@@ -141,6 +141,7 @@ void PasswordDialog::initializeUi()
                 if (shortName == QLatin1String("openconnect")) {
                     QAbstractButton *button = m_ui->buttonBox->button(QDialogButtonBox::Ok);
                     m_ui->buttonBox->removeButton(button);
+                    setMaximumWidth(QWIDGETSIZE_MAX);
                 }

                 setFocusProxy(m_vpnWidget);
diff --git a/vpn/openconnect/openconnectauth.cpp b/vpn/openconnect/openconnectauth.cpp
index a02b55b67..73a2b4f22 100644
--- a/vpn/openconnect/openconnectauth.cpp
+++ b/vpn/openconnect/openconnectauth.cpp
@@ -665,9 +665,10 @@ void OpenconnectAuthWidget::openWebEngine(const char *loginUri, QSemaphore *wait
     // QWebEngineView sizeHint fails to size window correctly based on contents
     // when QLayout::setSizeConstraint(QLayout::SetFixedSize) is set. Using same
     // size as webkitgtk is set to in GNOME/NetworkManager-openconnect.
-    webEngineView->setFixedSize(640, 480);
+    webEngineView->setMinimumSize(640, 480);

     d->ui.loginBoxLayout->addWidget(webEngineView);
+    d->ui.verticalLayout->setStretchFactor(d->ui.loginBox, 1);
 }

 void OpenconnectAuthWidget::addFormInfo(const QString &iconName, const QString &message)
